1	// The generator tick (tasks-dispatch DESIGN §5) — a pure function of the clock
2	// and the issue list, and the whole of the queue's scheduled machinery.
3	//
4	// Three jobs, all deterministic label mechanics: INSTANTIATE each recurring
5	// task's standing item when its anchor comes, READY blocked items whose
6	// dependencies have resolved and whose not-before has passed, and RECLAIM dead
7	// executor claims. It evaluates NO precondition and collects NO signal — the
8	// verdict happens once per period, at pickup, on the executor (§6.4) — which is
9	// what deletes the run-ledger watermark the slot machinery needed.
10	//
11	// `planTick` is the decision core, kept injectable so it tests with fixtures; the
12	// CLI shell below wires the GitHub reads and applies the ops.
13	
14	import { pathToFileURL } from 'node:url';
15	import { mostRecentAnchor, nextAnchor } from './anchors.mjs';
16	import { EXECUTING_LEASH_MS } from './leases.mjs';
17	import {
18	  WORK_PREFIX, BLOCKED, READY, EXECUTING, ORIGIN_SCHEDULE, NEEDS_HUMAN, OUTCOME_OBSOLETE,
19	  QUEUE_LABELS, EPISODE_MARKER, workItemTitle, parseWorkItemTitle, parseWorkItemBody,
20	  workItemBody, labelNames, hasLabel,
21	} from './work-item.mjs';
22	
23	// The tick owns the executing-leash reclaim because it is deterministic and
24	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
25	// ~25h (DESIGN §11, owner decision 6).
26	export { EXECUTING_LEASH_MS };
27	
28	const ms = (t) => (t == null ? null : new Date(t).getTime());
29	
30	// The ops `planTick` emits, each a label-and-body mechanic the shell applies:
31	//   { kind: 'dedupe',  issue, reason }            close, outcome:obsolete
32	//   { kind: 'create',  pack, task, labels, body } a task's standing item
33	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
34	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
35	//
36	// `items` is every `[claudinite-work]` issue the shell fetched (state=all for the
37	// scheduled families, open for the rest), each `{ number, title, body, state,
38	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
39	// state of a `Blocked-by` target that may not be a work item at all; an unknown
40	// number is never treated as closed, so an unreadable blocker delays rather than
41	// releases (the convergence-not-prevention posture).
42	export function planTick({
43	  tasks, items = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
44	  stateOf = () => null,
45	}) {
46	  const nowMs = ms(now);
47	  const ops = [];
48	  const closedByThisTick = new Set();
49	
50	  // ---- job 1: instantiate — calendar-only, no preconditions, no signals ----
51	  for (const task of tasks) {
52	    if (task.decl.frequency === 'manual') continue;
53	    const title = workItemTitle({ pack: task.pack, task: task.id });
54	    // The family is title-EXACT (no qualifier) and `origin:schedule` only, so
55	    // ad-hoc and fan-out items neither suppress nor consume an occurrence (§3).
56	    const family = items.filter((i) => (i.title ?? '').trim() === title && hasLabel(i, ORIGIN_SCHEDULE));
57	    const open = family
58	      .filter((i) => i.state === 'open' && !closedByThisTick.has(i.number))
59	      .sort((a, b) => a.number - b.number);
60	
61	    // F16 self-heal, FIRST: nothing documents that a REST list from another node
62	    // sees a creation seconds old, so a stale list can let a duplicate standing
63	    // item through. Assume it will happen rather than that it won't — close every
64	    // open family item but the oldest. Serialized by the tick's concurrency group,
65	    // so this can never race itself.
66	    for (const dup of open.slice(1)) {
67	      closedByThisTick.add(dup.number);
68	      ops.push({
69	        kind: 'dedupe', issue: dup.number, pack: task.pack, task: task.id,
70	        reason: `a duplicate standing item for ${task.pack}/${task.id} — #${open[0].number} is this task's standing item`,
71	      });
72	    }
73	    if (open.length) continue; // the standing item already exists
74	
75	    const anchor = mostRecentAnchor(task.decl.frequency, schedule, now);
76	    const anchorMs = anchor.getTime();
77	    // The occurrence guard has TWO halves (F13): an item CREATED at-or-after the
78	    // anchor covers this occurrence — and so does an item CLOSED at-or-after it,
79	    // because a rolled item created in an earlier period that ran and closed today
80	    // consumed today's occurrence. With the created_at half alone, the very next
81	    // tick after such a close creates a second item for the same occurrence: a
82	    // double execution.
83	    const covered = family.some((i) =>
84	      (ms(i.created_at) ?? -Infinity) >= anchorMs || (ms(i.closed_at) ?? -Infinity) >= anchorMs);
85	    if (covered) continue;
86	
87	    // A brand-new task's FIRST item is born blocked until its NEXT real anchor, so
88	    // adoption never fires weekly or monthly work off-anchor on the least-proven
89	    // repo (S25). Everything after that is born ready.
90	    const firstEver = family.length === 0;
91	    const notBefore = firstEver ? nextAnchor(task.decl.frequency, schedule, now).toISOString() : null;
92	    ops.push({
93	      kind: 'create', pack: task.pack, task: task.id, title,
94	      labels: [ORIGIN_SCHEDULE, firstEver ? BLOCKED : READY],
95	      body: workItemBody({
96	        taskPath: task.taskPath,
97	        notBefore,
98	        context: firstEver
99	          ? [`This task's first work item on this repo — born blocked until its first real anchor (${notBefore}), so adoption never runs it off-anchor.`]
100	          : [],
101	      }),
102	      notBefore,
103	    });
104	  }
105	
106	  // ---- job 2: ready whatever is due (any origin) --------------------------
107	  for (const item of items) {
108	    if (item.state !== 'open' || closedByThisTick.has(item.number)) continue;
109	    if (!hasLabel(item, BLOCKED) || hasLabel(item, NEEDS_HUMAN)) continue;
110	    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
111	    const blockersDone = blockedBy.every((n) => stateOf(n) === 'closed');
112	    const timeReached = notBefore === null || nowMs >= ms(notBefore);
113	    if (blockersDone && timeReached) ops.push({ kind: 'ready', issue: item.number });
114	  }
115	
116	  // ---- job 3: reclaim dead executor claims (DESIGN §11) -------------------
117	  const policyOf = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t.decl.on_interrupt ?? 'requeue']));
118	  for (const item of items) {
119	    if (item.state !== 'open' || !hasLabel(item, EXECUTING)) continue;
120	    const silentFor = nowMs - (ms(item.updated_at) ?? ms(item.created_at) ?? nowMs);
121	    if (silentFor < executingLeashMs) continue;
122	    const parsed = parseWorkItemTitle(item.title);
123	    const minutes = Math.round(executingLeashMs / 60e3);
124	    // `on_interrupt: 'needs-human'` is the at-most-once dial: a task that cannot
125	    // promise a safe re-run is not re-queued by a recovery path — it goes to a
126	    // human, who decides whether the interrupted run left anything behind.
127	    const oneShot = parsed && policyOf.get(`${parsed.pack}/${parsed.task}`) === 'needs-human';
128	    ops.push({
129	      kind: 'reclaim', issue: item.number, to: oneShot ? NEEDS_HUMAN : READY,
130	      reason: oneShot
131	        ? `The executor holding this item went silent for over ${minutes} minutes. This task declares \`on_interrupt: 'needs-human'\`, so nothing re-queues it automatically — check whether the interrupted run left anything behind, then re-queue it by hand.`
132	        : `Reclaimed: the executor holding this item went silent for over ${minutes} minutes. Returning it to the queue.`,
133	    });
134	  }
135	
136	  return { ops };
137	}
138	
139	// --- CLI: the thin I/O shell the vendored tick workflow invokes ---------------
140	// Reads the work-item list, plans, applies. All GitHub access is the Action's
141	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
142	// said it is out of the recurring work should not pay for the list that proves it.
143	
144	// Every `[claudinite-work]` issue, state=all, via the ISSUES list API — never the
145	// search index (S6/F11: search is eventually consistent, and a family list that
146	// misses a just-created item mints a duplicate standing item). Bounded by the
147	// scheduled families' need for closed history: closed items are only interesting
148	// back to the widest period, so the listing stops once it is past that.
149	export async function listWorkItems(gh, repo, { since = null } = {}) {
150	  const out = [];
151	  for (let page = 1; ; page += 1) {
152	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
153	      + (since ? `&since=${encodeURIComponent(since)}` : '');
154	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
155	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
156	    for (const i of json) {
157	      if (i.pull_request) continue;
158	      if (!(i.title ?? '').startsWith(WORK_PREFIX)) continue;
159	      out.push({
160	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
161	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
162	        updated_at: i.updated_at,
163	      });
164	    }
165	    if (json.length < 100) break;
166	  }
167	  return out;
168	}
169	
170	async function main() {
171	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
172	  const { discoverTasks } = await import('../discover.mjs');
173	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
174	  const { ensureLabels, addLabel, removeLabel, comment, closeIssue, createIssue } = await import('../github.mjs');
175	
176	  const root = process.cwd();
177	  const { repo } = actionRepoContext();
178	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
179	  const config = loadConfig(root);
180	
181	  console.log('## Claudinite tick\n');
182	  if (isDormant(config)) {
183	    console.log('- this project declares itself dormant — no items instantiated, readied or reclaimed');
184	    return;
185	  }
186	
187	  const gh = makeGh();
188	  const { tasks, errors } = await discoverTasks(root, config);
189	  for (const e of errors) console.log(`! ${e.what}`);
190	
191	  const now = new Date();
192	  // Closed items matter only back to the widest occurrence guard (a monthly
193	  // task's period); older history can never change a verdict.
194	  const since = new Date(now.getTime() - 40 * 86400e3).toISOString();
195	  const items = await listWorkItems(gh, repo, { since });
196	
197	  // A `Blocked-by` target need not be a work item — a fan-in blocks on whatever
198	  // its children are — so states come from the fetched items first and a direct
199	  // read otherwise.
200	  const known = new Map(items.map((i) => [i.number, i.state]));
201	  const wanted = new Set();
202	  for (const i of items) {
203	    if (i.state !== 'open' || !i.labels.includes(BLOCKED)) continue;
204	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
205	  }
206	  for (const n of wanted) {
207	    const { status, json } = await gh(`/repos/${repo}/issues/${n}`);
208	    known.set(n, status === 200 ? json?.state ?? null : null);
209	  }
210	
211	  const { ops } = planTick({
212	    tasks, items, now, schedule: config.taskScheduler, stateOf: (n) => known.get(n) ?? null,
213	  });
214	
215	  if (ops.some((o) => o.kind === 'create')) await ensureLabels(gh, repo, QUEUE_LABELS);
216	
217	  for (const op of ops) {
218	    if (op.kind === 'create') {
219	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
220	      if (res.number) console.log(`- created #${res.number} ${op.pack}/${op.task} [${op.labels.join(' ')}]`);
